perspectives.style:
@controls {
  bottom-left {
    showcase {
      as: buttons;
      mode: loose;

      option {
        label: "Social";
        selector: ["sets domain"="social"];
      }

      option {
        label: "Ecological";
        selector: ["sets domain"="ecological"];
      }

      option {
        label: "Technological";
        selector: ["sets domain"="technological"];
      }

      option {
        label: "Cross-SETS links";
        selector: ["sets scope"="cross-domain"];
      }

      option {
        label: "Unsourced";
        selector: ["sourced"="no"];
      }
    }

    text {
      value: "**Fill** = SETS domain: green = Ecological, blue = Social, orange = Technological<br>**Links:** blue = + (same direction), red = − (opposite direction); thicker = crosses a SETS boundary<br>**Shape:** square = stock, white centre = adaptive practice";
    }
  }
}

@settings {
  layout: static;
  theme: light;
  background-color: #FFFFFF;
  culling: false;
}

/* ---------- Elements: fill = SETS domain ---------- */
element {
  size: 120;
  font-size: 60;
  font-weight: bold;
  border-width: 0;
  shadow-visibility: hidden;
}

["sets domain"="ecological"] {
  color: #2E8B57;
}

["sets domain"="social"] {
  color: #3B82C4;
}

["sets domain"="technological"] {
  color: #E07B2A;
}

["element type"="stock"] {
  shape: square;
}

/* adaptive practices: white centre */
["adaptive practice"="yes"] {
  bullseye-visibility: visible;
  bullseye-color: #FFFFFF;
  bullseye-size: 0.5;
  bullseye-opacity: 1;
}

/* (no global curvature: each link keeps its own curve from the map) */
connection {
  size: 7;
  style: solid;
  arrow-visibility: visible;
  label: none;
  font-size: 100;
  font-weight: bold;
}

["polarity"="positive"] {
  color: #2166AC;
}

["polarity"="negative"] {
  color: #B2182B;
}

["sets scope"="cross-domain"] {
  size: 10;
}
